package tv.vela.launcher;

import android.content.*;
import android.graphics.Color;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.text.InputFilter;
import android.util.TypedValue;
import android.view.*;
import android.view.inputmethod.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;

/** Recycled text rows and lazy option pages, sharing the home's existing worker. */
final class CatalogFilterSheet extends FrameLayout {
    interface Result {void apply(CatalogFilters.Query query);}
    private final LibraryClient library;
    private final PlexClient.Section section;
    private final CatalogFilters.Query draft;
    private final ExecutorService io;
    private final Result result;
    private final Runnable close;
    private final boolean sorting;
    private final Handler main=new Handler(Looper.getMainLooper());
    private final ListView list;
    private final EditText search;
    private final TextView find,apply,reset,back,status,previous,next,count;
    private CatalogFilters.Options options;
    private CatalogFilters.Facet facet;
    private CatalogFilters.Choices choices;
    private Future<?> work;
    private String term="",account;
    private boolean live=true,loading;
    private int generation,rootPosition;
    private BaseAdapter adapter;
    private static String t(String pt,String en,String es){return Ui.tr(pt,en,es);}
    CatalogFilterSheet(Context context,LibraryClient library,PlexClient.Section section,CatalogFilters.Query query,boolean sorting,ExecutorService worker,Result result,Runnable close){
        super(context);this.library=library;this.section=section;draft=query.copy();this.sorting=sorting;io=worker;this.result=result;this.close=close;account=library.identity();
        search=new EditText(context);search.setId(View.generateViewId());search.setSingleLine();search.setSaveEnabled(false);search.setFilters(new InputFilter[]{new InputFilter.LengthFilter(240)});search.setTextColor(0xFFF7F7FA);search.setHintTextColor(0xFFAEB6C4);search.setTextSize(TypedValue.COMPLEX_UNIT_PX,24);search.setPadding(24,0,24,0);search.setBackground(round(0xFF242D3D));search.setImeOptions(EditorInfo.IME_ACTION_SEARCH);put(search,84,12,768,72);
        find=button(t("Buscar","Search","Buscar"),864,12,240,()->search());
        apply=button(t("Aplicar","Apply","Aplicar"),1200,12,540,()->apply());reset=button(t("Restaurar","Reset","Restablecer"),1200,116,540,()->{draft.values.clear();draft.search="";draft.sort="";draft.descending=true;hideKeyboard();result.apply(draft.copy());});back=button(t("Voltar","Back","Volver"),1200,220,540,()->{if(!back())close.run();});
        status=label("",23);status.setMaxLines(9);status.setGravity(Gravity.TOP);put(status,1206,338,530,330);
        list=new ListView(context);list.setId(View.generateViewId());list.setDivider(new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT));list.setDividerHeight(12);list.setPadding(6,6,6,6);list.setClipToPadding(true);list.setSelector(round(0xFF3A4658));list.setCacheColorHint(Color.TRANSPARENT);list.setVerticalScrollBarEnabled(false);list.setItemsCanFocus(false);list.setNextFocusRightId(apply.getId());list.setNextFocusUpId(search.getId());put(list,78,130,1038,564);
        previous=button(t("‹ Anterior","‹ Previous","‹ Anterior"),84,766,260,()->loadChoices(Math.max(0,choices.offset-CatalogFilters.CHOICES)));next=button(t("Seguinte ›","Next ›","Siguiente ›"),844,766,260,()->loadChoices(choices.nextOffset()));count=label("",21);count.setGravity(Gravity.CENTER);put(count,354,766,480,76);
        search.setOnEditorActionListener((v,a,e)->{search();return true;});list.setOnItemClickListener((p,v,position,id)->choose(position));previous.setVisibility(GONE);next.setVisibility(GONE);count.setVisibility(GONE);loadOptions();
    }
    private TextView label(String text,int size){TextView v=new TextView(getContext());v.setText(text);v.setTextSize(TypedValue.COMPLEX_UNIT_PX,size);v.setTextColor(0xFFE4E7EF);v.setTypeface(Ui.medium);v.setIncludeFontPadding(false);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
    private GradientDrawable round(int color){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(18);return g;}
    private void put(View view,int x,int y,int w,int h){LayoutParams p=new LayoutParams(w,h);p.leftMargin=x;p.topMargin=y;addView(view,p);}
    private TextView button(String title,int x,int y,int w,Runnable action){TextView v=label(title,24);v.setId(View.generateViewId());v.setGravity(Gravity.CENTER);v.setSingleLine();v.setEllipsize(android.text.TextUtils.TruncateAt.END);v.setFocusable(true);v.setDefaultFocusHighlightEnabled(false);v.setBackground(round(0xFF273144));v.setOnFocusChangeListener((view,on)->{v.setBackground(round(on?0xFFF5F6FA:0xFF273144));v.setTextColor(on?0xFF141924:0xFFE4E7EF);});v.setOnClickListener(view->action.run());put(v,x,y,w,76);return v;}
    private void hideKeyboard(){((InputMethodManager)getContext().getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(getWindowToken(),0);}
    private void cancel(){generation++;if(work!=null)work.cancel(true);work=null;loading=false;}
    private void loadOptions(){cancel();loading=true;apply.setEnabled(false);status.setText(t("Carregando filtros do servidor…","Loading server filters…","Cargando filtros del servidor…"));int epoch=generation;work=io.submit(()->{try{CatalogFilters.Options fresh=library.filters(section);main.post(()->{if(!valid(epoch))return;options=fresh;loading=false;apply.setEnabled(true);root();});}catch(Exception error){main.post(()->{if(!valid(epoch))return;loading=false;status.setText(t("Não foi possível ler os filtros. Use Buscar para tentar novamente.","Could not read filters. Use Search to retry.","No se han podido leer los filtros. Pulsa Buscar para reintentar."));find.requestFocus();});}});}
    private boolean valid(int epoch){return live&&generation==epoch&&account.equals(library.identity());}
    private void root(){facet=null;choices=null;term="";search.setText(draft.search);search.setHint(t("Buscar título","Search titles","Buscar por título"));search.setFilters(new InputFilter[]{new InputFilter.LengthFilter(240)});search.setVisibility(sorting?GONE:VISIBLE);find.setVisibility(sorting?GONE:VISIBLE);apply.setVisibility(sorting?GONE:VISIBLE);reset.setVisibility(sorting?GONE:VISIBLE);previous.setVisibility(GONE);next.setVisibility(GONE);count.setVisibility(GONE);LayoutParams p=(LayoutParams)list.getLayoutParams();p.topMargin=sorting?12:130;p.height=sorting?752:564;list.setLayoutParams(p);
        List<String> titles=new ArrayList<>();if(sorting){for(CatalogFilters.Sort sort:options.sorts){boolean selected=sort.key.equals(draft.sort.isEmpty()?(library.isJellyfin()?"DateCreated":"addedAt"):draft.sort);if(selected)rootPosition=titles.size()+(draft.descending?0:1);titles.add((selected&&draft.descending?"✓ ":"")+sortLabel(sort.key,sort.title)+" · "+t("Decrescente","Descending","Descendente"));titles.add((selected&&!draft.descending?"✓ ":"")+sortLabel(sort.key,sort.title)+" · "+t("Crescente","Ascending","Ascendente"));}status.setText(t("A ordem vale para todas as páginas desta biblioteca.","This order applies to every page in this library.","El orden se aplica a todas las páginas de esta biblioteca."));}else{for(CatalogFilters.Facet f:options.facets){List<CatalogFilters.Choice> selected=draft.values.getOrDefault(f.id,Collections.emptyList());String detail="";for(CatalogFilters.Choice c:selected)detail+=(detail.isEmpty()?"":", ")+choiceLabel(f,c);titles.add((selected.isEmpty()?"":"✓ ")+label(f.id,f.title)+(detail.isEmpty()?"":" · "+detail));}status.setText(t("Combine filtros e escolha Aplicar. Nada muda até aplicar. Restaurar volta às últimas adições.","Combine filters, then Apply. Nothing changes until applied. Reset returns to latest additions.","Combina filtros y pulsa Aplicar. No cambia nada hasta aplicarlos. Restablecer vuelve a las últimas subidas."));}rows(titles);list.setSelection(Math.min(rootPosition,Math.max(0,titles.size()-1)));list.requestFocus();
    }
    private void rows(List<String> titles){adapter=new BaseAdapter(){public int getCount(){return titles.size();}public Object getItem(int p){return titles.get(p);}public long getItemId(int p){return p;}public View getView(int p,View reuse,ViewGroup parent){TextView v=reuse instanceof TextView?(TextView)reuse:label("",25);v.setPadding(22,0,22,0);v.setSingleLine();v.setEllipsize(android.text.TextUtils.TruncateAt.END);v.setText(titles.get(p));v.setLayoutParams(new AbsListView.LayoutParams(-1,82));return v;}};list.setAdapter(adapter);}
    private void choose(int position){if(loading||options==null)return;if(sorting){CatalogFilters.Sort s=options.sorts.get(position/2);draft.sort=s.key;draft.descending=position%2==0;result.apply(draft.copy());return;}if(facet==null){draft.search=search.getText().toString().trim();rootPosition=position;facet=options.facets.get(position);term="";search.setText("");search.setFilters(new InputFilter[]{new InputFilter.LengthFilter(80)});search.setHint(label(facet.id,facet.title));loadChoices(0);}else{CatalogFilters.Choice choice=choices.items.get(position);if(!draft.selected(facet.id,choice.value)&&draft.count()>=CatalogFilters.MAX_VALUES&&(facet.multiple||!draft.values.containsKey(facet.id))){status.setText(t("Máximo de 24 opções. Remova uma para continuar.","Maximum 24 selections. Remove one to continue.","Máximo de 24 opciones. Quita alguna para continuar."));return;}draft.toggle(facet,choice);showChoices(position);}}
    private void search(){if(options==null){loadOptions();return;}if(facet==null){apply();return;}term=search.getText().toString().trim();hideKeyboard();loadChoices(0);}
    private void loadChoices(int offset){if(facet==null)return;cancel();loading=true;apply.setEnabled(false);list.setEnabled(false);previous.setEnabled(false);next.setEnabled(false);status.setText(t("Carregando opções…","Loading choices…","Cargando opciones…"));int epoch=generation;CatalogFilters.Facet selected=facet;String prefix=term;work=io.submit(()->{try{CatalogFilters.Choices page=library.choices(section,selected,offset,prefix);main.post(()->{if(!valid(epoch)||facet!=selected)return;loading=false;apply.setEnabled(true);choices=page;list.setEnabled(true);showChoices(0);});}catch(Exception error){main.post(()->{if(!valid(epoch)||facet!=selected)return;loading=false;apply.setEnabled(true);status.setText(t("Não foi possível carregar as opções. Refine a busca ou volte para tentar novamente.","Could not load choices. Refine the search or go back to retry.","No se han podido cargar las opciones. Concreta la búsqueda o vuelve para reintentar."));find.requestFocus();});}});}
    private void showChoices(int position){List<String> labels=new ArrayList<>();for(CatalogFilters.Choice c:choices.items)labels.add((draft.selected(facet.id,c.value)?"✓ ":"   ")+choiceLabel(facet,c));rows(labels);list.setSelection(position);list.requestFocus();previous.setVisibility(VISIBLE);next.setVisibility(VISIBLE);count.setVisibility(VISIBLE);previous.setEnabled(choices.offset>0);next.setEnabled(choices.next());previous.setAlpha(previous.isEnabled()?1:.4f);next.setAlpha(next.isEnabled()?1:.4f);count.setText((choices.items.isEmpty()?0:choices.offset+1)+"–"+(choices.offset+choices.received)+" / "+choices.total);status.setText(label(facet.id,facet.title)+"\n\n"+(facet.multiple?t("Escolha uma ou várias opções.","Choose one or more options.","Elige una o varias opciones."):t("Escolha uma opção. Selecione de novo para remover.","Choose one option. Select it again to remove it.","Elige una opción. Selecciónala otra vez para quitarla."))+"\n\n"+t("Aplicar atualiza a biblioteca inteira, não apenas esta página.","Apply updates the whole library, not only this page.","Aplicar filtra toda la biblioteca, no solo esta página."));if(choices.items.isEmpty()){status.append("\n\n"+t("Sem resultados.","No results.","Sin resultados."));find.requestFocus();}}
    private void apply(){if(loading||options==null||!account.equals(library.identity()))return;if(facet==null&&!sorting)draft.search=search.getText().toString().trim();if(draft.count()>CatalogFilters.MAX_VALUES){status.setText(t("Máximo de 24 opções. Remova uma para continuar.","Maximum 24 selections. Remove one to continue.","Máximo de 24 opciones. Quita alguna para continuar."));return;}hideKeyboard();result.apply(draft.copy());}
    boolean back(){if(facet==null)return false;cancel();list.setEnabled(true);root();return true;}
    void release(){live=false;cancel();main.removeCallbacksAndMessages(null);hideKeyboard();list.setAdapter(null);search.setText("");removeAllViews();}
    static String label(String key,String fallback){String k=key.contains(".")?key.substring(key.lastIndexOf('.')+1):key;switch(k){case "$state":return t("Estado","Watch status","Estado de visto");case "genre":case "genres":case "genreIds":return t("Gênero","Genre","Género");case "year":case "years":return t("Ano","Year","Año");case "decade":return t("Década","Decade","Década");case "contentRating":case "officialRatings":return t("Classificação etária","Content rating","Clasificación por edades");case "collection":return t("Coleção","Collection","Colección");case "country":return t("País","Country","País");case "director":return t("Diretor","Director","Director");case "actor":return t("Elenco","Cast","Reparto");case "writer":return t("Roteirista","Writer","Guionista");case "producer":return t("Produtor","Producer","Productor");case "studio":case "studioIds":return t("Estúdio","Studio","Estudio");case "personIds":return t("Pessoas","People","Personas");case "label":case "tags":return t("Etiquetas","Tags","Etiquetas");case "resolution":return t("Resolução","Resolution","Resolución");case "audioLanguage":case "audioLanguages":return t("Idioma de áudio","Audio language","Idioma de audio");case "subtitleLanguage":case "subtitleLanguages":return t("Idioma de legendas","Subtitle language","Idioma de subtítulos");case "isFavorite":return t("Favoritos","Favorites","Favoritos");case "hasSubtitles":return t("Legendas","Subtitles","Subtítulos");case "is3D":return "3D";case "isHd":return "HD";case "is4K":return "4K";case "minCommunityRating":return t("Nota mínima","Minimum rating","Puntuación mínima");case "seriesStatus":return t("Estado da série","Series status","Estado de la serie");default:return fallback;}}
    static String sortLabel(String key,String fallback){String k=key.contains(".")?key.substring(key.lastIndexOf('.')+1):key;switch(k){case "addedAt":case "DateCreated":return t("Data de adição","Date added","Fecha de incorporación");case "titleSort":case "SortName":return t("Título","Title","Título");case "year":case "ProductionYear":return t("Ano","Year","Año");case "originallyAvailableAt":case "PremiereDate":return t("Estreia","Release date","Estreno");case "rating":case "CriticRating":return t("Crítica","Critic rating","Puntuación de la crítica");case "audienceRating":case "CommunityRating":return t("Público","Audience rating","Puntuación del público");case "userRating":return t("Sua nota","Your rating","Tu puntuación");case "duration":case "Runtime":return t("Duração","Runtime","Duración");case "lastViewedAt":case "DatePlayed":case "SeriesDatePlayed":return t("Última reprodução","Last played","Última reproducción");case "viewCount":case "PlayCount":return t("Reproduções","Play count","Número de reproducciones");case "DateLastContentAdded":return t("Último episódio adicionado","Last content added","Último contenido añadido");case "OfficialRating":return label("officialRatings",fallback);case "Studio":return label("studio",fallback);case "VideoBitRate":return t("Taxa de bits","Bitrate","Tasa de bits");default:return fallback;}}
    private static String choiceLabel(CatalogFilters.Facet f,CatalogFilters.Choice c){if(f.id.equals("$state")){if(c.value.equals("unwatched"))return t("Não vistos","Unwatched","Sin ver");if(c.value.equals("watched"))return t("Vistos","Watched","Vistos");if(c.value.equals("progress"))return t("Em andamento","In progress","En progreso");}if(Arrays.asList("isFavorite","hasSubtitles","is3D","isHd","is4K","unwatched").contains(f.id)&&(c.value.equals("true")||c.value.equals("1")))return t("Sim","Yes","Sí");if(Arrays.asList("isFavorite","hasSubtitles","is3D","isHd","is4K","unwatched").contains(f.id)&&(c.value.equals("false")||c.value.equals("0")))return t("Não","No","No");if(f.id.equals("seriesStatus")){if(c.value.equals("Continuing"))return t("Em exibição","Continuing","En emisión");if(c.value.equals("Ended"))return t("Finalizada","Ended","Finalizada");if(c.value.equals("Unreleased"))return t("Não lançada","Unreleased","Sin estrenar");}return c.title;}
}
